import{z as i,x as d,o as E,c as r,q as o,j as n,D as e,d as A,s as t,S as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"拥塞控制的实现","description":"","frontmatter":{"title":"拥塞控制的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/npk-congestion-implementation.md","filePath":"cs/npk-congestion-implementation.md","lastUpdated":1791413859000}'),B={name:"cs/npk-congestion-implementation.md"};function p(C,a,l,_,h,m){const c=d("Mermaid");return E(),r("div",null,[a[2]||(a[2]=o('<h1 id="拥塞控制的实现" tabindex="-1">拥塞控制的实现 <a class="header-anchor" href="#拥塞控制的实现" aria-label="Permalink to &quot;拥塞控制的实现&quot;">​</a></h1><div class="epigraph"><p>算法论文画的是窗口随时间的曲线；协议栈里它是一次函数调用加几个整型字段——每个 ACK 到达时改几个数，其余时间窗口只是一份无人触碰的账。</p><footer>—— 据 RFC 5681、RFC 6928；Linux tcp_congestion_ops 接口与 net/ipv4/tcp_input.c 口径整理</footer></div><p><a href="/cs/npk-tcp-state-machine">上一课</a>把 ESTABLISHED 的 sock 落在四元组哈希表里；拥塞变量 <code>snd_cwnd</code>、<code>ssthresh</code> 就栖在这个对象上，随状态生灭。主干课已拆过 AIMD 的动机（<a href="/cs/tcp-congestion">拥塞控制</a>）、Reno 与 Cubic 的曲线（<a href="/cs/reno-cubic">Reno 与 Cubic</a>）与 <a href="/cs/bbr">BBR</a> 的另起炉灶；<a href="/cs/aimd-dynamics">AIMD 动力学</a>给了收敛证明。本课不重推任何一条曲线，只写它们共同的实现落点：算法怎么插拔、窗口何时被改、记分板怎么记、发包节奏由谁执行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个实现问题决定了算法能不能按论文工作：算法必须可在不重编内核的情况下按连接更换；丢包判定只能发生在 ACK 到达的那条路径上，发送线程自己无从知道对端收没收到；重传队列必须能按序号快速定位「哪些段已确认、哪些成洞」。不这么做会错在哪：把窗口更新挂在定时器或应用调用上，曲线就不再跟着 ACK 走，多流公平性与反应性全部落空；把记分板做成顺序扫描，大窗口（十万段量级）下每个 ACK 扫一遍队列，CPU 先于网络饱和；忽略 pacing，窗口允许的突发会在微秒级全数压进瓶颈队列，自己制造丢包再把自己减窗。</p><p><span class="marginnote">术语翻译：记分板（scoreboard）就是发送端的一本账——「哪些段已确认、哪些还在飞、哪些洞等着补」。对端靠 SACK 块在 ACK 里捎话「我收到了第几到第几段」，本端就在这本账上打勾；恢复结束时账上没勾的区间就是重传对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件事各有一个落点。插拔：每个算法定义一张 <code>tcp_congestion_ops</code> 函数表——钩住窗口增长、拥塞事件、慢启动阈值；<code>setsockopt(TCP_CONGESTION)</code> 按连接换表，<code>tcp_congestion_control</code> 定全机默认。Cubic 与 BBR 的差别就是两张函数表的差别。更新时机：每个 ACK 进入 <code>tcp_ack</code>——RTT 采样、累计确认推进、SACK 块记账，然后按丢包判定结果驱动一个拥塞子状态机（Open、Disorder、CWR、Recovery、Loss 五态）：正常则调用算法的窗口增长钩子，判定丢包（三个重复 ACK 或 RACK 按时间断定）则迁入恢复态并减窗，ECN 的 CE 标记走 CWR 态减一次。记账：重传队列是一棵按序号索引的红黑树，SACK 块在树上标「已到、未确认」，恢复结束时树上仍留的区间就是重传对象。节奏：窗口只答「最多飞多少」，何时刻满由 <code>sk_pacing_rate</code> 回答，通常交给 <a href="/cs/tx-path-qdisc">fq qdisc</a> 在出口执行——把突发摊成匀速。</p>',8)),(E(),n(s,null,{default:e(()=>[t(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACK%5B%22ACK%20%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20SAMPLE%5B%22RTT%20%E9%87%87%E6%A0%B7%E4%B8%8E%20SACK%20%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20SAMPLE%20--%3E%20JUDGE%7B%22%E4%B8%A2%E5%8C%85%20%2F%20ECN%20%2F%20%E6%AD%A3%E5%B8%B8%22%7D%0A%20%20JUDGE%20--%3E%7C%22%E6%AD%A3%E5%B8%B8%22%7C%20OPEN%5B%22Open%EF%BC%9A%E8%B0%83%E7%AE%97%E6%B3%95%E5%A2%9E%E9%95%BF%E9%92%A9%E5%AD%90%22%5D%0A%20%20JUDGE%20--%3E%7C%22%E4%B8%A2%E6%88%96%E6%A0%87%E8%AE%B0%22%7C%20REC%5B%22Recovery%20%2F%20CWR%EF%BC%9A%E5%87%8F%E7%AA%97%22%5D%0A%20%20REC%20--%3E%20OPEN%0A%20%20OPEN%20--%3E%20CW%5B%22snd_cwnd%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20CW%20--%3E%20PACE%5B%22sk_pacing_rate%20%E2%86%92%20fq%20%E5%87%BA%E5%8F%A3%E5%8C%80%E9%80%9F%E5%8F%91%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>落点的结构性理由：ACK 处理是全栈唯一同时看得见「对端视角」与「本端队列」的位置，窗口逻辑放这里才闭环。函数表把算法从状态机里解耦——恢复、记分板、RTO 是公共底座，Cubic 与 BBR 只换增长与减窗钩子，这就是「同一套丢包信号下的窗口几何」能并存的原因。红黑树让按序号的操作（查洞、清已确认）都是对数阶，记分板从「位图标记」进化为「树上区间」，万段窗口也不怕。pacing 把拥塞控制的两个自由度分开：<code>cwnd</code> 管量，<code>pacing_rate</code> 管速，前者由 ACK 驱动、后者按 BDP 折算——只认窗口不认节奏的实现，会在窗口恢复的瞬间把整窗突发打出去，等于自己给自己喂丢包信号。</p><p><span class="marginnote">两个易错点的数字：初始窗口自 RFC 6928 起是 10 个 MSS，不是教科书旧图里的 1；<code>snd_cwnd</code> 以段为单位，不足一段的零头由 <code>snd_cwnd_cnt</code> 攒——把窗口当字节数直接加减，微 MSS 与对齐的细节立刻算错。<code>ss -ti</code> 的 cwnd 字段读的就是它，单位是段。</span></p><p><span class="marginnote">数字实例：窗口 20 段时判定丢包，减窗动作就是把阈值砍半——<code>ssthresh=10</code>，随后每过一个 RTT 才线性加 1 段，从 10 爬回 20 要 10 个 RTT。若 RTT 是 50 毫秒，一次丢包就损失约半秒钟的爬坡时间；这就是丢包信号贵的直观账。又：十万段窗口下查一个序号，红黑树约走 17 步（\\(\\log_2 10^5\\)），顺序扫描要走十万步——每个 ACK 都扫的话差距是四个数量级。</span></p><p><span class="marginnote">直觉类比：<code>cwnd</code> 像货运公司的「在途上限」——最多允许多少辆车同时在路上；<code>pacing_rate</code> 则像发车时刻表。只有上限没有时刻表，窗口一恢复就十辆车同时挤上独木桥（瓶颈队列），桥堵死、车掉了（丢包），公司再把自己减产——不分批的突发等于自导自演一次拥塞事件。</span></p>',5)),(E(),n(s,null,{default:e(()=>[t(c,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E8%BF%9E%E6%8E%A5%E5%BB%BA%E7%AB%8B%22%5D%20--%3E%20DEF%5B%22%E6%8C%82%E4%B8%8A%E5%85%A8%E6%9C%BA%E9%BB%98%E8%AE%A4%E7%AE%97%E6%B3%95%E8%A1%A8%22%5D%0A%20%20DEF%20--%3E%20APP%7B%22%E5%BA%94%E7%94%A8%20setsockopt%20%E6%8D%A2%E7%AE%97%E6%B3%95%3F%22%7D%0A%20%20APP%20--%3E%7C%22%E6%98%AF%22%7C%20SWAP%5B%22%E6%8D%A2%E6%88%90%E6%9C%AC%E8%BF%9E%E6%8E%A5%E7%9A%84%E5%87%BD%E6%95%B0%E8%A1%A8%22%5D%0A%20%20APP%20--%3E%7C%22%E5%90%A6%22%7C%20KEEP%5B%22%E6%B2%BF%E7%94%A8%E9%BB%98%E8%AE%A4%E8%A1%A8%22%5D%0A%20%20SWAP%20--%3E%20HOOK%5B%22ACK%20%E8%B7%AF%E5%BE%84%E8%B0%83%E7%94%A8%E9%92%A9%E5%AD%90%22%5D%0A%20%20KEEP%20--%3E%20HOOK%0A%20%20HOOK%20--%3E%20G%5B%22%E5%A2%9E%E9%95%BF%E9%92%A9%E5%AD%90%3A%20Cubic%20%2F%20BBR%20%E5%90%84%E8%87%AA%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20HOOK%20--%3E%20L%5B%22%E5%87%8F%E7%AA%97%E9%92%A9%E5%AD%90%3A%20%E5%85%AC%E5%85%B1%E7%8A%B6%E6%80%81%E6%9C%BA%E8%A7%A6%E5%8F%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推 AIMD 的收敛（<a href="/cs/aimd-dynamics">aimd-dynamics</a>）、Cubic 的时间立方（<a href="/cs/reno-cubic">reno-cubic</a>）、BBR 的带宽建模（<a href="/cs/bbr-v2-v3">bbr-v2-v3</a>）与 DCTCP 的标记比例（<a href="/cs/dctcp">dctcp</a>）；RTO 定时器的估计与退避归 <a href="/cs/tcp-rto">RTO 与 Karn</a>。无线链路上的假丢包问题也不在此展开。后课默认：拥塞变量已挂上 sock、随 ACK 更新、发包有节奏；下一课转向应用与内核的交界——这些对象如何被套接字层包装成交付给进程的 fd。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>拥塞控制的实现三落点：算法函数表可插拔、更新只在 ACK 路径、记分板是序号红黑树。</li><li>ESTABLISHED 内部还有五态拥塞子状态机，由丢包判定与 ECN 驱动迁移。</li><li>pacing 把「发多少」与「多快发」分开，突发窗不摊开就是自造丢包。</li><li>初始窗口 10 MSS、窗口按段记账——数字与单位错了，曲线就对不上论文。</li><li>出处：RFC 5681、RFC 6928；Ha, Rhee and Xu（CUBIC）；Cardwell 等（BBR）；Linux tcp_congestion_ops 口径整理。</li></ul>',4))])}const u=i(B,[["render",p]]);export{T as __pageData,u as default};
